mapper.sql:
WHERE R.CMPNY_CD       = #{cmpnyCd}
  AND R.INITIATOR_TYPE = 'ADMIN'
  AND R.DEL_YN         = 'N'

  AND R.SITE_CD        = #{siteCd}


  AND R.REQ_TYPE       = #{reqType}


  AND R.REQ_STATUS     = #{reqStatus}


  AND R.INSERT_DATE   >= STR_TO_DATE(CONCAT(#{fromDate}, '000000'), '%Y%m%d%H%i%s')


  AND R.INSERT_DATE   <= STR_TO_DATE(CONCAT(#{toDate}, '235959'), '%Y%m%d%H%i%s')


  AND TU.USER_NM LIKE CONCAT('%', #{userNm}, '%')



  AND R.TARGET_USER_CD IN (
      SELECT NU.USER_CD
        FROM TB_USER NU
       WHERE NU.CMPNY_CD = #{cmpnyCd}
         AND NU.SITE_CD  = #{siteCd}


         AND NU.NODE_CD IN (
             WITH RECURSIVE sub AS (
                 SELECT N.NODE_CD
                   FROM TB_SITE_NODE N
                  WHERE N.CMPNY_CD = #{cmpnyCd} AND N.SITE_CD = #{siteCd} AND N.NODE_CD = #{nodeCd}
                 UNION ALL
                 SELECT C.NODE_CD
                   FROM TB_SITE_NODE C
                   JOIN sub S2
                     ON C.CMPNY_CD = #{cmpnyCd} AND C.SITE_CD = #{siteCd} AND C.PARENT_NODE_CD = S2.NODE_CD
             )
             SELECT NODE_CD FROM sub
         )


         AND NU.NODE_CD = #{nodeCd}


  )
